import{_ as i,c as a,o as r,aj as t}from"./chunks/framework.8bp-HAn5.js";const d=JSON.parse('{"title":"中间节点","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"node-middle.md","filePath":"node-middle.md"}'),n={name:"node-middle.md"};function o(e,l,s,p,h,u){return r(),a("div",null,[...l[0]||(l[0]=[t(`<h1 id="中间节点" tabindex="-1">中间节点 <a class="header-anchor" href="#中间节点" aria-label="Permalink to “中间节点”">​</a></h1><pre><code>中间节点通常用于蓝图中的逻辑处理，数值计算等操作，处理数据逻辑的输入，同时输出数据或逻辑
</code></pre><h2 id="计算" tabindex="-1">计算 <a class="header-anchor" href="#计算" aria-label="Permalink to “计算”">​</a></h2><h3 id="加" tabindex="-1">加 <a class="header-anchor" href="#加" aria-label="Permalink to “加”">​</a></h3><p>将两个数值相加，输出结果。</p><p><strong>输入：</strong></p><ul><li>A：第一个数值</li><li>B：第二个数值</li></ul><p><strong>输出：</strong></p><ul><li>A + B：两个数值的和</li></ul><h3 id="减" tabindex="-1">减 <a class="header-anchor" href="#减" aria-label="Permalink to “减”">​</a></h3><p>将两个数值相减，输出结果。</p><p><strong>输入：</strong></p><ul><li>A：被减数</li><li>B：减数</li></ul><p><strong>输出：</strong></p><ul><li>A - B：两个数值的差</li></ul><h3 id="乘" tabindex="-1">乘 <a class="header-anchor" href="#乘" aria-label="Permalink to “乘”">​</a></h3><p>将两个数值相乘，输出结果。</p><p><strong>输入：</strong></p><ul><li>A：第一个数值</li><li>B：第二个数值</li></ul><p><strong>输出：</strong></p><ul><li>A x B：两个数值的积</li></ul><h3 id="除" tabindex="-1">除 <a class="header-anchor" href="#除" aria-label="Permalink to “除”">​</a></h3><p>将两个数值相除，输出结果。</p><p><strong>输入：</strong></p><ul><li>A：被除数</li><li>B：除数</li></ul><p><strong>输出：</strong></p><ul><li>A ÷ B：两个数值的商</li></ul><h3 id="长度" tabindex="-1">长度 <a class="header-anchor" href="#长度" aria-label="Permalink to “长度”">​</a></h3><p>计算向量的长度（模长），基于勾股定理计算。</p><p><strong>输入：</strong></p><ul><li>x：x坐标</li><li>y：y坐标</li></ul><p><strong>输出：</strong></p><ul><li>长度：向量(x, y)的长度，计算公式为 √(x² + y²)</li></ul><h2 id="转换" tabindex="-1">转换 <a class="header-anchor" href="#转换" aria-label="Permalink to “转换”">​</a></h2><h3 id="取整数" tabindex="-1">取整数 <a class="header-anchor" href="#取整数" aria-label="Permalink to “取整数”">​</a></h3><p>将浮点数转换为整数，支持三种取整方式。</p><p><strong>输入：</strong></p><ul><li>向下取整：输入数值，使用Math.floor向下取整</li><li>向上取整：输入数值，使用Math.ceil向上取整</li><li>四舍五入：输入数值，使用Math.round四舍五入</li></ul><p><strong>输出：</strong></p><ul><li>输出：取整后的结果</li></ul><p><strong>说明：</strong> 节点会优先使用第一个有值的输入，如果第一个输入有值则使用向下取整，否则检查第二个输入，以此类推。</p><h3 id="平方根" tabindex="-1">平方根 <a class="header-anchor" href="#平方根" aria-label="Permalink to “平方根”">​</a></h3><p>计算数值的平方根。</p><p><strong>输入：</strong></p><ul><li>输入：需要开平方的数值</li></ul><p><strong>输出：</strong></p><ul><li>开平方：输入值的平方根</li></ul><h3 id="绝对值" tabindex="-1">绝对值 <a class="header-anchor" href="#绝对值" aria-label="Permalink to “绝对值”">​</a></h3><p>计算数值的绝对值。</p><p><strong>输入：</strong></p><ul><li>输入：需要计算绝对值的数值</li></ul><p><strong>输出：</strong></p><ul><li>绝对值：输入值的绝对值（始终为正数或0）</li></ul><h3 id="正负反转" tabindex="-1">正负反转 <a class="header-anchor" href="#正负反转" aria-label="Permalink to “正负反转”">​</a></h3><p>将数值的正负号反转。</p><p><strong>输入：</strong></p><ul><li>输入：需要反转的数值</li></ul><p><strong>输出：</strong></p><ul><li>输出：输入值乘以-1的结果</li></ul><h2 id="角度" tabindex="-1">角度 <a class="header-anchor" href="#角度" aria-label="Permalink to “角度”">​</a></h2><h3 id="角度差" tabindex="-1">角度差 <a class="header-anchor" href="#角度差" aria-label="Permalink to “角度差”">​</a></h3><p>计算两个角度或向量之间的角度差。</p><p><strong>输入：</strong></p><ul><li>角度A：第一个角度或向量</li><li>角度B：第二个角度或向量</li></ul><p><strong>输出：</strong></p><ul><li>输出：两个角度之间的差值（0-180度之间）</li></ul><p><strong>属性：</strong></p><ul><li>输入的类型：可选择&quot;角度&quot;或&quot;向量&quot; <ul><li>角度模式：直接比较两个角度值，返回较小的角度差</li><li>向量模式：输入为包含x和y属性的对象，计算两个向量之间的夹角</li></ul></li></ul><h3 id="将位置转换为角度" tabindex="-1">将位置转换为角度 <a class="header-anchor" href="#将位置转换为角度" aria-label="Permalink to “将位置转换为角度”">​</a></h3><p>根据x、y坐标计算对应的角度值。</p><p><strong>输入：</strong></p><ul><li>x坐标：x轴坐标</li><li>y坐标：y轴坐标</li></ul><p><strong>输出：</strong></p><ul><li>角度：从原点指向(x, y)的角度值（0-360度）</li></ul><p><strong>说明：</strong> 使用atan2函数计算角度，返回角度范围在-180到180度之间。</p><h3 id="将角度转换为位置" tabindex="-1">将角度转换为位置 <a class="header-anchor" href="#将角度转换为位置" aria-label="Permalink to “将角度转换为位置”">​</a></h3><p>根据角度和斜边长计算对应的x、y坐标。</p><p><strong>输入：</strong></p><ul><li>角度：角度值（度）</li><li>斜边长：从原点到目标点的距离</li></ul><p><strong>输出：</strong></p><ul><li>x长：x轴方向的长度</li><li>y长：y轴方向的长度</li></ul><p><strong>说明：</strong> 使用三角函数cos和sin计算坐标值。</p><h2 id="比较" tabindex="-1">比较 <a class="header-anchor" href="#比较" aria-label="Permalink to “比较”">​</a></h2><h3 id="等于" tabindex="-1">等于 <a class="header-anchor" href="#等于" aria-label="Permalink to “等于”">​</a></h3><p>判断两个数值是否相等。</p><p><strong>输入：</strong></p><ul><li>A：第一个数值</li><li>B：第二个数值</li></ul><p><strong>输出：</strong></p><ul><li>A == B?：如果A等于B输出1，否则输出0</li></ul><h3 id="小于" tabindex="-1">小于 <a class="header-anchor" href="#小于" aria-label="Permalink to “小于”">​</a></h3><p>判断第一个数值是否小于第二个数值。</p><p><strong>输入：</strong></p><ul><li>A：第一个数值</li><li>B：第二个数值</li></ul><p><strong>输出：</strong></p><ul><li>A &lt; B?：如果A小于B输出1，否则输出0</li></ul><h3 id="大于" tabindex="-1">大于 <a class="header-anchor" href="#大于" aria-label="Permalink to “大于”">​</a></h3><p>判断第一个数值是否大于第二个数值。</p><p><strong>输入：</strong></p><ul><li>A：第一个数值</li><li>B：第二个数值</li></ul><p><strong>输出：</strong></p><ul><li>A &gt; B?：如果A大于B输出1，否则输出0</li></ul><h3 id="范围内" tabindex="-1">范围内 <a class="header-anchor" href="#范围内" aria-label="Permalink to “范围内”">​</a></h3><p>判断数值B是否在A和C的范围内。</p><p><strong>输入：</strong></p><ul><li>A：最小值（可通过属性设置）</li><li>B：要判断的数值</li><li>C：最大值（可通过属性设置）</li></ul><p><strong>输出：</strong></p><ul><li>结果：如果B在范围内输出1，否则输出0</li></ul><p><strong>属性：</strong></p><ul><li>最小值A：范围的最小值</li><li>最大值C：范围的最大值</li><li>A和B比较：选择&quot;&lt;&quot;或&quot;&lt;=&quot;</li><li>B和C比较：选择&quot;&lt;&quot;或&quot;&lt;=&quot;</li></ul><p><strong>说明：</strong> 节点标题会根据比较符号动态显示，例如&quot;A&lt;B&lt;=C&quot;。</p><h2 id="逻辑" tabindex="-1">逻辑 <a class="header-anchor" href="#逻辑" aria-label="Permalink to “逻辑”">​</a></h2><h3 id="全部正确" tabindex="-1">全部正确 <a class="header-anchor" href="#全部正确" aria-label="Permalink to “全部正确”">​</a></h3><p>逻辑与运算，所有输入都为真（非0且非undefined）时输出1。</p><p><strong>输入：</strong></p><ul><li>A：第一个输入值</li><li>B：第二个输入值</li></ul><p><strong>输出：</strong></p><ul><li>结果：只有当A和B都为真时输出1，否则输出0</li></ul><p><strong>说明：</strong> 如果任意输入为0或undefined，输出为0。</p><h3 id="任意一个正确" tabindex="-1">任意一个正确 <a class="header-anchor" href="#任意一个正确" aria-label="Permalink to “任意一个正确”">​</a></h3><p>逻辑或运算，任意一个输入为真时输出1。</p><p><strong>输入：</strong></p><ul><li>A：第一个输入值</li><li>B：第二个输入值</li><li>C：第三个输入值（可选）</li></ul><p><strong>输出：</strong></p><ul><li>结果：如果A、B、C中任意一个为真（非0且非undefined）时输出1，否则输出0</li></ul><h3 id="全部触发" tabindex="-1">全部触发 <a class="header-anchor" href="#全部触发" aria-label="Permalink to “全部触发”">​</a></h3><p>事件逻辑与，所有输入事件都触发后才输出事件。</p><p><strong>输入：</strong></p><ul><li>触发_0：第一个触发事件</li><li>触发_1：第二个触发事件</li><li>...（可动态添加更多输入）</li></ul><p><strong>输出：</strong></p><ul><li>触发：当所有输入事件都触发后，输出触发事件</li></ul><p><strong>属性：</strong></p><ul><li>触发后重置：如果开启，触发后自动重置状态，可以再次触发</li></ul><p><strong>说明：</strong> 节点会记录每个输入是否已触发，当所有输入都触发后才会输出。</p><h3 id="任意触发" tabindex="-1">任意触发 <a class="header-anchor" href="#任意触发" aria-label="Permalink to “任意触发”">​</a></h3><p>事件逻辑或，任意一个输入事件触发时立即输出事件。</p><p><strong>输入：</strong></p><ul><li>触发_0：第一个触发事件</li><li>触发_1：第二个触发事件</li><li>...（可动态添加更多输入）</li></ul><p><strong>输出：</strong></p><ul><li>触发：任意输入事件触发时，立即输出触发事件</li></ul><p><strong>说明：</strong> 节点会自动检测连接的节点，动态添加输入接口。</p><h3 id="反转结果" tabindex="-1">反转结果 <a class="header-anchor" href="#反转结果" aria-label="Permalink to “反转结果”">​</a></h3><p>逻辑非运算，将输入的真假值反转。</p><p><strong>输入：</strong></p><ul><li>A：输入值</li></ul><p><strong>输出：</strong></p><ul><li>结果：如果A为真（非0）输出0，如果A为假（0或undefined）输出1</li></ul><h2 id="变化" tabindex="-1">变化 <a class="header-anchor" href="#变化" aria-label="Permalink to “变化”">​</a></h2><h3 id="随机整数" tabindex="-1">随机整数 <a class="header-anchor" href="#随机整数" aria-label="Permalink to “随机整数”">​</a></h3><p>生成随机整数。</p><p><strong>输入：</strong></p><ul><li>随机范围：随机数的最大值（可选，默认为10000000）</li></ul><p><strong>输出：</strong></p><ul><li>结果：生成的随机整数（0到输入值-1之间）</li></ul><p><strong>属性：</strong></p><ul><li>模式：选择&quot;仅一次&quot;或&quot;每次随机&quot; <ul><li>仅一次：节点首次执行时生成随机数，之后保持不变</li><li>每次随机：每次执行都生成新的随机数</li></ul></li></ul><h3 id="延迟触发" tabindex="-1">延迟触发 <a class="header-anchor" href="#延迟触发" aria-label="Permalink to “延迟触发”">​</a></h3><p>延迟指定时间后触发事件。</p><p><strong>输入：</strong></p><ul><li>开始：触发延迟的输入事件</li><li>time_in_s：延迟时间（秒，可通过属性设置）</li></ul><p><strong>输出：</strong></p><ul><li>结束时：延迟时间到达后触发的输出事件</li></ul><p><strong>属性：</strong></p><ul><li>秒：延迟的秒数（支持小数）</li></ul><p><strong>说明：</strong> 如果延迟时间为0，表示等待1帧后立即触发。可以同时处理多个延迟任务。</p><h3 id="间隔触发" tabindex="-1">间隔触发 <a class="header-anchor" href="#间隔触发" aria-label="Permalink to “间隔触发”">​</a></h3><p>每隔指定时间间隔触发一次事件。</p><p><strong>输入：</strong></p><ul><li>interval：间隔时间（毫秒，可通过属性设置）</li></ul><p><strong>输出：</strong></p><ul><li>触发：每隔指定时间触发一次</li></ul><p><strong>属性：</strong></p><ul><li>毫秒：间隔的毫秒数</li></ul><p><strong>说明：</strong> 节点启动后会自动开始计时，每隔指定时间触发一次。节点标题会显示当前的间隔时间。</p><h3 id="计数" tabindex="-1">计数 <a class="header-anchor" href="#计数" aria-label="Permalink to “计数”">​</a></h3><p>计数器，可以增加、减少或重置数值。</p><p><strong>输入：</strong></p><ul><li>开始值：计数器的初始值（可通过属性设置）</li><li>增加：触发增加计数的事件</li><li>减少：触发减少计数的事件</li><li>重置：触发重置计数的事件</li></ul><p><strong>输出：</strong></p><ul><li>数值：当前的计数值</li><li>变化：计数值变化时触发的事件</li></ul><p><strong>属性：</strong></p><ul><li>开始值：计数器的初始值</li><li>模式：选择计数模式 <ul><li>无限制：可以无限增加或减少</li><li>范围限制：限制在最小值和最大值之间</li><li>循环：超过最大值时回到最小值</li><li>来回：在最小值和最大值之间来回变化</li></ul></li><li>最小值：计数的最小值（模式为&quot;无限制&quot;时禁用）</li><li>最大值：计数的最大值（模式为&quot;无限制&quot;时禁用）</li><li>步进模式：选择&quot;乘以时间&quot;或&quot;不乘以时间&quot; <ul><li>乘以时间：步进值会根据时间变化，适合连续计数</li><li>不乘以时间：每次触发固定增加或减少步进值</li></ul></li><li>步进数值：每次增加或减少的数值</li></ul><p><strong>说明：</strong> 在&quot;来回&quot;模式下，计数器到达边界时会自动改变方向。</p><h3 id="标记状态" tabindex="-1">标记状态 <a class="header-anchor" href="#标记状态" aria-label="Permalink to “标记状态”">​</a></h3><p>用于标记和存储一个状态值，可以在不同节点间共享。</p><p><strong>输入：</strong></p><ul><li>值：要设置的状态值</li><li>修改：触发修改状态的事件</li></ul><p><strong>输出：</strong></p><ul><li>输出：当前的状态值</li></ul><p><strong>属性：</strong></p><ul><li>状态名称：自定义状态的名称（模式为&quot;自定义&quot;时使用）</li><li>初始值：状态的初始值</li><li>状态权限：选择状态的存储范围 <ul><li>仅当前分镜：只在当前蓝图内有效</li><li>所有分镜：在所有分镜间共享</li><li>Window：全局有效</li></ul></li><li>模式：选择预定义状态或自定义状态 <ul><li>自定义：使用自定义状态名称</li><li>动画是否播放中、是否不可交互、游戏是否开始等：预定义的状态</li></ul></li><li>初始化时将自定义状态值赋值：开启后，启动时自动将初始值赋给状态</li></ul><p><strong>说明：</strong> 节点标题会显示当前的状态名称。通过&quot;修改&quot;事件可以更新状态值。</p><h3 id="数据结构" tabindex="-1">数据结构 <a class="header-anchor" href="#数据结构" aria-label="Permalink to “数据结构”">​</a></h3><p>遍历对象或数组，每次循环输出一个键值对。</p><p><strong>输入：</strong></p><ul><li>挂载：要遍历的对象或数组</li></ul><p><strong>输出：</strong></p><ul><li>key：当前项的键（对象）或索引（数组）</li><li>value：当前项的值</li><li>触发：每次循环时触发的事件</li></ul><p><strong>说明：</strong></p><ul><li>如果输入是数组，会遍历每个元素，key为索引</li><li>如果输入是对象，会遍历每个属性，key为属性名</li><li>每次循环都会触发一次输出事件</li></ul><h3 id="对象取值" tabindex="-1">对象取值 <a class="header-anchor" href="#对象取值" aria-label="Permalink to “对象取值”">​</a></h3><p>从对象中获取指定属性的值。</p><p><strong>输入：</strong></p><ul><li>obj：要取值的对象</li></ul><p><strong>输出：</strong></p><ul><li>property：指定属性的值</li></ul><p><strong>属性：</strong></p><ul><li>输入key：要获取的属性名称</li></ul><p><strong>说明：</strong> 节点标题在折叠状态下会显示为&quot;获取.[属性名]&quot;。</p><h3 id="数组取值" tabindex="-1">数组取值 <a class="header-anchor" href="#数组取值" aria-label="Permalink to “数组取值”">​</a></h3><p>从数组或字符串中获取指定索引的值。</p><p><strong>输入：</strong></p><ul><li>array：要取值的数组、表格或字符串</li><li>index：索引值（可通过属性设置）</li></ul><p><strong>输出：</strong></p><ul><li>value：指定索引的值</li></ul><p><strong>属性：</strong></p><ul><li>index：索引值（从0开始）</li></ul><p><strong>说明：</strong> 节点标题在折叠状态下会显示为&quot;获取.[索引]&quot;。如果索引为小数，会自动向下取整。</p><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to “工具”">​</a></h2><h3 id="无线传送发射" tabindex="-1">无线传送发射 <a class="header-anchor" href="#无线传送发射" aria-label="Permalink to “无线传送发射”">​</a></h3><p>向所有监听该事件的节点发送数据和事件，实现无线连接。</p><p><strong>输入：</strong></p><ul><li>附带值：要发送的数据</li><li>发送：触发发送的事件</li></ul><p><strong>属性：</strong></p><ul><li>发送事件：事件的名称标识</li></ul><p><strong>说明：</strong> 节点会将附带值发送给所有监听相同事件名称的&quot;无线传送接收&quot;节点。节点标题在折叠状态下会显示为&quot;发送事件.[事件名]&quot;。</p><h3 id="无线传送接收" tabindex="-1">无线传送接收 <a class="header-anchor" href="#无线传送接收" aria-label="Permalink to “无线传送接收”">​</a></h3><p>接收来自&quot;无线传送发射&quot;节点发送的数据和事件。</p><p><strong>输出：</strong></p><ul><li>接收值：接收到的数据</li><li>接收：接收到数据时触发的事件</li></ul><p><strong>属性：</strong></p><ul><li>接收事件：要监听的事件名称（需与发射节点的事件名称一致）</li></ul><p><strong>说明：</strong> 节点会监听指定名称的事件，当有对应的发射节点发送数据时，会输出接收到的值和触发事件。节点标题在折叠状态下会显示为&quot;接收事件.[事件名]&quot;。</p><h3 id="输出逻辑线" tabindex="-1">输出逻辑线 <a class="header-anchor" href="#输出逻辑线" aria-label="Permalink to “输出逻辑线”">​</a></h3><p>根据输入值选择触发不同的输出接口。</p><p><strong>输入：</strong></p><ul><li>输入值：用于选择输出接口的数值</li><li>触发：触发选择的事件</li></ul><p><strong>输出：</strong></p><ul><li>output_0：当输入值为0时触发</li><li>output_1：当输入值为1时触发</li><li>...（可动态添加更多输出）</li></ul><p><strong>说明：</strong> 输入值会被转换为整数，然后触发对应索引的输出接口。如果输入值超出输出接口数量，则不会触发任何输出。</p><h3 id="动态取值" tabindex="-1">动态取值 <a class="header-anchor" href="#动态取值" aria-label="Permalink to “动态取值”">​</a></h3><p>动态获取引用节点的属性值。</p><p><strong>输入：</strong></p><ul><li>引用节点：要获取属性的节点（类型为lgraphNode）</li></ul><p><strong>输出：</strong></p><ul><li>动态输出：根据引用节点的属性自动生成输出接口</li></ul><p><strong>说明：</strong> 节点会自动检测引用节点的所有属性，为每个属性创建一个输出接口。当引用节点改变时，输出接口会自动更新。</p><h3 id="动态赋值" tabindex="-1">动态赋值 <a class="header-anchor" href="#动态赋值" aria-label="Permalink to “动态赋值”">​</a></h3><p>动态设置引用节点的属性值。</p><p><strong>输入：</strong></p><ul><li>引用节点：要设置属性的节点（类型为lgraphNode）</li><li>触发赋值：触发赋值的事件</li><li>动态输入：根据引用节点的属性自动生成输入接口</li></ul><p><strong>说明：</strong> 节点会自动检测引用节点的所有属性，为每个属性创建一个输入接口。触发赋值时，会将所有输入的值赋给引用节点的对应属性。</p><h3 id="js文本" tabindex="-1">js文本 <a class="header-anchor" href="#js文本" aria-label="Permalink to “js文本”">​</a></h3><p>直接执行JavaScript代码片段。</p><p><strong>输入：</strong></p><ul><li>输入参数：代码中可以使用的输入值（变量名为valueA）</li></ul><p><strong>输出：</strong></p><ul><li>输出结果：代码执行后的输出值（变量名为valueB）</li></ul><p><strong>属性：</strong></p><ul><li>执行代码片段：要执行的JavaScript代码</li></ul><p><strong>说明：</strong></p><ul><li>代码中可以使用变量valueA作为输入值</li><li>代码执行后，变量valueB的值会作为输出</li><li>代码执行错误会在控制台显示警告，不会中断程序运行</li></ul><h2 id="蓝图" tabindex="-1">蓝图 <a class="header-anchor" href="#蓝图" aria-label="Permalink to “蓝图”">​</a></h2><h3 id="分支蓝图" tabindex="-1">分支蓝图 <a class="header-anchor" href="#分支蓝图" aria-label="Permalink to “分支蓝图”">​</a></h3><p>用于创建子蓝图，实现逻辑的模块化和复用。</p><p><strong>说明：</strong> 分支蓝图允许将复杂的逻辑封装成独立的子蓝图，通过输入和输出接口与主蓝图交互。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to “输入”">​</a></h3><p>分支蓝图的输入接口，用于接收来自主蓝图的数据。</p><p><strong>说明：</strong> 在分支蓝图内部，可以通过输入节点获取主蓝图传入的数据。</p><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to “输出”">​</a></h3><p>分支蓝图的输出接口，用于向主蓝图返回数据或触发事件。</p><p><strong>说明：</strong> 在分支蓝图内部，可以通过输出节点向主蓝图返回数据或触发事件。</p>`,271)])])}const c=i(n,[["render",o]]);export{d as __pageData,c as default};
